<script>

// ---- cursor-tracked spotlight in the hero ----
(function () {

    var hero = document.querySelector('.hero');

    if (!hero) return;

    hero.addEventListener('mousemove', function (e) {

        var rect = hero.getBoundingClientRect();

        var x = ((e.clientX - rect.left) / rect.width) * 100;
        var y = ((e.clientY - rect.top) / rect.height) * 100;

        hero.style.setProperty('--mx', x + '%');
        hero.style.setProperty('--my', y + '%');

    });

})();


// ---- nav bar solidifies on scroll ----
(function () {

    var nav = document.getElementById('siteNav');
    var toTop = document.getElementById('toTop');

    if (!nav) return;

    function onScroll() {

        if (window.scrollY > 60) {
            nav.classList.add('scrolled');
        } else {
            nav.classList.remove('scrolled');
        }

        if (toTop) {

            if (window.scrollY > 700) {
                toTop.classList.add('visible');
            } else {
                toTop.classList.remove('visible');
            }

        }

    }

    document.addEventListener('scroll', onScroll, { passive: true });
    onScroll();

})();


// ---- scroll-triggered reveal ----
(function () {

    var targets = document.querySelectorAll('.reveal');

    if (!('IntersectionObserver' in window)) {

        targets.forEach(function (el) {
            el.classList.add('in-view');
        });

        return;

    }

    var observer = new IntersectionObserver(function (entries) {

        entries.forEach(function (entry) {

            if (entry.isIntersecting) {

                entry.target.classList.add('in-view');
                observer.unobserve(entry.target);

            }

        });

    }, { threshold: 0.15, rootMargin: '0px 0px -60px 0px' });

    targets.forEach(function (el) {
        observer.observe(el);
    });

})();


// ---- 3D tilt on every framed image (category tiles, painting
// cards, the about photo) so each one responds like a canvas
// being viewed from a slightly different angle ----
(function () {

    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        return;
    }

    var tiltEls = document.querySelectorAll('.tilt');

    tiltEls.forEach(function (el) {

        el.addEventListener('mousemove', function (e) {

            var r = el.getBoundingClientRect();

            var px = (e.clientX - r.left) / r.width - 0.5;
            var py = (e.clientY - r.top) / r.height - 0.5;

            var rx = (py * -7).toFixed(2);
            var ry = (px * 7).toFixed(2);

            el.style.transform = 'perspective(800px) rotateX(' + rx + 'deg) rotateY(' + ry + 'deg)';

        });

        el.addEventListener('mouseleave', function () {
            el.style.transform = 'perspective(800px) rotateX(0deg) rotateY(0deg)';
        });

    });

})();

</script>


<!-- =====================================================
     SPLASH SCREEN TIMER (separate script, does not touch
     the block above)
===================================================== -->
<script>
(function () {
    var splash = document.getElementById('splashScreen');
    if (!splash) return;

    var params = new URLSearchParams(window.location.search);
    if (params.get('admin') === '1') {
        splash.remove();
        return;
    }

    var prevOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    setTimeout(function () {
        splash.classList.add('splash-fade-out');
        document.body.style.overflow = prevOverflow;
        setTimeout(function () {
            if (splash.parentNode) splash.parentNode.removeChild(splash);
        }, 650);
    }, 3000);
})();
</script>

